/bin/bash -c "python3 - <<'PY'
import math
from collections import Counter
points=[(0,0),(0,1),(1,0),(1,1)]
def distribution(vals):
    c=Counter(vals)
    return {x:n/len(vals) for x,n in c.items()}
def js(p,q):
    keys=p.keys()|q.keys()
    m={x:(p.get(x,0)+q.get(x,0))/2 for x in keys}
    def kl(r):
        return sum(v*math.log(v/m[x]) for x,v in r.items() if v)
    return (kl(p)+kl(q))/2
for name,coord in [('impute B',1),('impute A',0)]:
    groups=[[h for h in points if h[coord]==g] for g in [0,1]]
    discrepancy=abs(sum(h[0] for h in groups[1])/len(groups[1])-sum(h[0] for h in groups[0])/len(groups[0]))
    print(name,{'representation_JS':js(*[distribution(g) for g in groups]),'prediction_DP':discrepancy})
print('Maximal JS (natural logarithms):',math.log(2))
PY"
